from PIL import Image
import numpy as np
for path in ['/app/output/initial','/app/output/reopen','/app/output/yaw_shift']:
 for cam,roi in [('front',(110,205,70,112)),('side',(80,175,65,105)),('top',(120,205,135,205))]:
  im=np.array(Image.open(f'{path}/last/{cam}.jpg')); x0,x1,y0,y1=roi; yy,xx=np.mgrid[y0:y1,x0:x1]; p=im[y0:y1,x0:x1]
  # bright mask, remove greenish color; for top pick robot upper body maybe no
  m=(p.mean(2)>175)&(p[:,:,1]<p[:,:,0]*1.25)&(p[:,:,0]<p[:,:,1]*1.25)
  if m.sum()>0: print(path,cam,m.sum(),np.mean(xx[m]),np.mean(yy[m]))
PY

